    <template v-else>
      <div class="filters"><label>模板名称<el-input v-model="draftKeyword" maxlength="100" clearable aria-label="模板名称筛选" @keyup.enter="search" /></label><label>有效状态<el-select v-model="draftStatus" clearable placeholder="全部状态" @change="search"><el-option label="有效" :value="1" /><el-option label="已失效" :value="0" /></el-select></label><el-button :disabled="busy" @click="search">查询</el-button><el-button :disabled="busy" @click="reset">重置</el-button></div>
