      <el-alert v-if="listError" :title="listError" type="error" :closable="false"><template #default><el-button link @click="load()">重试列表</el-button></template></el-alert>
      <div v-if="!listError" class="table-scroll"><el-table :data="list" row-key="id" border v-loading="loading"><el-table-column prop="id" label="ID" width="75" /><el-table-column label="模板名称" min-width="190"><template #default="{ row }">{{ row.title || '未命名模板' }}<el-tag v-if="!row.valid" type="danger" size="small">历史数据需核对</el-tag></template></el-table-column><el-table-column label="适用范围" min-width="200"><template #default="{ row }">{{ scopeLabel(row) }}</template></el-table-column><el-table-column prop="coupon_price" label="面额" width="100" /><el-table-column prop="use_min_price" label="使用门槛" width="110" /><el-table-column prop="valid_days" label="有效天数" width="100" /><el-table-column prop="sort" label="排序" width="80" /><el-table-column prop="issue_count" label="发布次数" width="100" /><el-table-column label="状态" width="100"><template #default="{ row }">{{ row.status ? '有效' : '已失效' }}</template></el-table-column><el-table-column label="添加时间" min-width="165"><template #default="{ row }">{{ timeLabel(row.add_time) }}</template></el-table-column><el-table-column label="操作" :fixed="compact ? undefined : 'right'" width="270"><template #default="{ row }"><div class="actions"><el-button link :disabled="busy || loading" @click="openDetail(row, 'view')">详情 / 发布记录</el-button><el-button v-if="canPublish" link type="primary" :disabled="busy || loading || !!uncertainOperation || !row.valid || !row.status || row.deleted" @click="openDetail(row, 'publish')">发布</el-button><el-button v-if="canManage && row.status" link type="warning" :disabled="busy || loading || !!uncertainOperation" @click="confirmAction(row, 'invalidate')">立即失效</el-button><el-button v-if="canManage" link type="danger" :disabled="busy || loading || !!uncertainOperation" @click="confirmAction(row, 'delete')">删除</el-button></div></template></el-table-column></el-table></div>
      <el-pagination v-if="ready && !loading && !listError" :current-page="page" :page-size="15" :total="count" layout="total, prev, pager, next" @current-change="load" class="pager" :disabled="busy" />
