.coupon-templates{min-width:0}.heading,.actions,.filters,.selected{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.heading{justify-content:space-between;margin-bottom:16px}.heading h2{margin:0;font-size:20px}.hint{color:#707783;font-size:12px;line-height:1.7;overflow-wrap:anywhere}.filters{margin:14px 0;align-items:end}.filters label{display:grid;gap:6px;flex:1 1 180px;font-size:13px}.filters :deep(.el-input){min-width:0;flex:1 1 170px}.filters :deep(.el-select){width:100%}.table-scroll{max-width:100%;overflow-x:auto}.pager{justify-content:flex-end;margin:18px 0;flex-wrap:wrap}.actions :deep(.el-button + .el-button){margin-left:0}.selected{margin:12px 0}.selected :deep(.el-tag){max-width:100%;white-space:normal;height:auto;min-height:24px;overflow-wrap:anywhere}.notice{margin:12px 0;overflow-wrap:anywhere}.notice pre{white-space:pre-wrap;overflow-wrap:anywhere}.snapshot{display:grid;grid-template-columns:140px minmax(0,1fr);gap:12px;line-height:1.6}.snapshot dd{margin:0;overflow-wrap:anywhere}.snapshot ul{padding-left:20px}.dates{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.dates input{min-width:0;width:100%;box-sizing:border-box;border:1px solid #dcdfe6;border-radius:4px;padding:7px;font:inherit}.inset{margin-left:125px}:deep(.el-form-item__content){min-width:0}:deep(.el-select),:deep(.el-cascader){max-width:100%}
@media(max-width:650px){.filters{display:grid;grid-template-columns:minmax(0,1fr)}.dates{grid-template-columns:minmax(0,1fr)}.snapshot{grid-template-columns:100px minmax(0,1fr)}.inset{margin-left:0}.pager{justify-content:center}:deep(.el-form-item__label){width:110px!important}}
